  await page.setContent(html);await page.waitForFunction(()=>document.querySelector('.usage-total')?.textContent==='40');const footer=page.locator('.hq-footer'),supporters=footer.locator('.supporters'),list=supporters.locator('ul'),repo=footer.getByRole('link',{name:'SWARM repository',exact:true});
  assert.equal(await footer.locator('.brand-links a').first().getAttribute('href'),'https://github.com/flowwweb/swarm');assert.deepEqual(await list.locator('li').allTextContents(),names);assert.equal(await list.count(),1);assert.equal(await supporters.locator('a,img,[aria-hidden=true]').count(),0,'unverified brands remain text, no fake destinations or duplicate speech');
  await repo.focus();await page.keyboard.press('Enter');assert.deepEqual(await page.evaluate(()=>window.opened),['https://github.com/flowwweb/swarm']);const hit=await repo.boundingBox();assert.ok(hit.width>=44&&hit.height>=44);
  await supporters.scrollIntoViewIfNeeded();await supporters.hover();assert.equal(await list.evaluate(e=>getComputedStyle(e).animationPlayState),'paused');await supporters.focus();assert.ok(await supporters.evaluate(e=>e===document.activeElement));assert.equal(await list.evaluate(e=>getComputedStyle(e).animationName),'none');
  await page.emulateMedia({reducedMotion:'reduce'});await page.evaluate(()=>document.activeElement.blur());assert.equal(await list.evaluate(e=>getComputedStyle(e).animationName),'none');assert.equal(await list.evaluate(e=>getComputedStyle(e).flexWrap),'wrap');
  await footer.scrollIntoViewIfNeeded();const inside=await footer.evaluate(e=>{const f=e.getBoundingClientRect();return [...e.querySelectorAll('li')].every(n=>{const r=n.getBoundingClientRect();return r.left>=f.left&&r.right<=f.right&&r.top>=f.top&&r.bottom<=f.bottom;});});assert.ok(inside);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth&&document.body.scrollWidth<=document.body.clientWidth+1));
