async function roleMediaProof(browser,html,out){
 const results=[];
 for(const [width,height] of [[1440,1000],[834,1112],[390,844]])for(const mode of ['native-unavailable','available','digest-mismatch','unsafe-url','missing-url','decode-failure']){
  const page=await browser.newPage({viewport:{width,height},colorScheme:'dark',reducedMotion:'reduce'}),errors=[],requests=[];
  page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});
  await page.route('https://role-fixture.invalid/**',async route=>{if(route.request().url()==='https://role-fixture.invalid/')return route.fulfill({contentType:'text/html',body:html});requests.push(route.request().url());assert.equal(route.request().url(),'https://role-fixture.invalid/assets/role-avatars/designer.png');await route.fulfill({contentType:'image/svg+xml',body:mode==='decode-failure'?'invalid image':'<svg xmlns="http://www.w3.org/2000/svg" width="160" height="80"><rect width="160" height="80" fill="#64748b"/></svg>'});});
  // Calibration pixels exercise decode/containment only; they are not admitted role art and are never captured as a product screenshot.
  await page.goto('https://role-fixture.invalid/');await page.waitForFunction(()=>document.querySelector('.usage-total')?.textContent==='40');await navigationClick(page,'.library-nav a[href="#roles"]');await page.locator('[data-role-open=designer]').waitFor();
  await page.evaluate(mode=>{const r=window.roles[0];if(mode==='native-unavailable')r.avatar=null;if(mode==='digest-mismatch')r.avatar.digest='b'.repeat(64);if(mode==='unsafe-url')r.avatar.url='https://untrusted.invalid/image.png';if(mode==='missing-url')delete r.avatar.url;},mode);
  await page.locator('[data-library-load]').click();const trigger=page.locator('[data-role-open=designer]');await trigger.focus();await page.keyboard.press('Enter');const form=page.locator('[data-role-form]');await form.waitFor();
  assert.equal(await page.locator('[data-role-catalog] img').count(),0,'catalog uses small manifest icons only');assert.equal(await form.locator('[data-role-avatar-note]').textContent(),'Image uploads are unavailable. Current artwork stays active until you save.');
  const avatar=form.locator('.role-avatar'),img=avatar.locator('img');
  if(mode==='available'){await img.evaluate(e=>e.decode());assert.equal(await avatar.getAttribute('data-role-avatar-state'),'available');assert.deepEqual(await img.evaluate(e=>({width:e.naturalWidth,height:e.naturalHeight,fit:getComputedStyle(e).objectFit})),{width:160,height:80,fit:'contain'});assert.equal(await img.getAttribute('alt'),'Designer avatar');assert.equal(await avatar.locator('.role-avatar-fallback').isVisible(),false);}
  else {await page.waitForFunction(()=>document.querySelector('[data-role-form] .role-avatar')?.dataset.roleAvatarState==='unavailable');assert.ok(await avatar.locator('.role-avatar-fallback').isVisible());assert.match(await avatar.locator('.role-avatar-fallback').getAttribute('aria-label'),/avatar unavailable/);if(mode==='decode-failure')assert.equal(await img.isVisible(),false);else assert.equal(await img.count(),0);}
  const geometry=await form.locator('.role-avatar-box').boundingBox();assert.ok(geometry.width>=(width===834?128:160)-1,'large responsive avatar preview');assert.equal(geometry.width,geometry.height);assert.ok(geometry.x>=0&&geometry.x+geometry.width<=width);
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth&&document.body.scrollWidth<=document.body.clientWidth+1));assert.equal(await page.evaluate(()=>window.roleWrites||0),0,'viewing media never writes');assert.deepEqual(errors,[]);assert.equal(requests.length,['available','decode-failure'].includes(mode)?1:0,'rejected media never requested');
  if(mode==='native-unavailable'){await page.screenshot({path:`${out}/roles-native-unavailable-${width}.png`});await form.locator('[name=purpose]').fill('Preserve admitted artwork');const actions=width<=700?page.locator('#inspector footer'):form.locator('.editor-actions');await actions.getByRole('button',{name:'Save role',exact:true}).click();await form.waitFor({state:'hidden'});assert.equal(await page.evaluate(()=>window.lastRoleWrite.manifest.avatar_asset_digest),'a'.repeat(64));assert.equal(await page.evaluate(()=>window.lastRoleWrite.expected_active_version),'builtin:'+'d'.repeat(64));assert.ok(await trigger.evaluate(e=>e===document.activeElement));}
  else {if(width<=700)await page.keyboard.press('Escape');else await form.getByRole('button',{name:'Cancel',exact:true}).click();assert.ok(await trigger.evaluate(e=>e===document.activeElement));}
  results.push({width,mode,geometry,requests,errors});await page.close();
 }
 writeFileSync(`${out}/ROLE-MEDIA-PROOF.json`,JSON.stringify({class:'local mock-browser; calibration pixels are not admitted assets; screenshots show native avatar:null only',results},null,2));
}

async function roleThemeProof(browser,html,out){
 const results=[];
 for(const scheme of ['light','dark'])for(const [width,height] of [[1440,1000],[834,1112],[390,844]]){
  const page=await browser.newPage({viewport:{width,height},colorScheme:scheme,reducedMotion:'reduce'}),errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.setContent(html);await page.waitForFunction(()=>document.querySelector('.usage-total')?.textContent==='40');await navigationClick(page,'.library-nav a[href="#roles"]');const trigger=page.locator('[data-role-open="designer"]');await trigger.waitFor();await trigger.focus();await page.keyboard.press('Enter');const form=page.locator('[data-role-form]');await form.waitFor();
  if(width===1440){assert.ok(await form.locator('.editor-actions').evaluate(e=>e.getBoundingClientRect().bottom<=innerHeight),'Roles04 primary actions visible in first desktop viewport');const catalog=await page.locator('.library-catalog').boundingBox(),editor=await page.locator('.library-editor').boundingBox();assert.ok(Math.abs(catalog.height-editor.height)<2,'shared catalog/detail height');const loop=await form.locator('a[href="#loops"]').boundingBox(),actions=await form.locator('.editor-actions').boundingBox();assert.ok(loop.y+loop.height<=actions.y,'Loops row never concealed by footer');}assert.equal(await form.locator('details.library-custody').count(),0,'secondary provenance consolidated into More');assert.equal(await form.locator('[data-role-more] .library-custody').count(),1);assert.equal(await page.locator('[data-role-open=designer] [data-role-icon]').getAttribute('data-role-icon'),'palette');
  await page.screenshot({path:`${out}/role-theme-${scheme}-${width}.png`});
  const result=await form.locator('[name=name],[name=purpose],[name=instructions]').evaluateAll(es=>{
   const c=document.createElement('canvas');c.width=c.height=1;const ctx=c.getContext('2d');const rgb=color=>{ctx.clearRect(0,0,1,1);ctx.fillStyle=color;ctx.fillRect(0,0,1,1);return [...ctx.getImageData(0,0,1,1).data].slice(0,3);};const lum=rgb=>rgb.map(n=>{n/=255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4;}).reduce((a,n,i)=>a+n*[.2126,.7152,.0722][i],0);
   return es.map(e=>{const s=getComputedStyle(e),a=lum(rgb(s.color)),b=lum(rgb(s.backgroundColor));return {name:e.name,foreground:s.color,background:s.backgroundColor,contrast:(Math.max(a,b)+.05)/(Math.min(a,b)+.05),height:e.getBoundingClientRect().height};});
  });for(const field of result){assert.ok(field.contrast>=4.5,JSON.stringify({scheme,width,...field}));assert.ok(field.height>=44);}
  assert.ok(await form.locator('[name=name]').evaluate(e=>e===document.activeElement));await page.keyboard.press('Tab');assert.ok(await form.locator('[name=purpose]').evaluate(e=>e===document.activeElement));
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth&&document.body.scrollWidth<=document.body.clientWidth+1));
  if(width<=700)await page.keyboard.press('Escape');else await form.getByRole('button',{name:'Cancel',exact:true}).click();assert.ok(await trigger.evaluate(e=>e===document.activeElement));assert.deepEqual(errors,[]);results.push({scheme,width,fields:result,errors});await page.close();
 }
 writeFileSync(`${out}/THEME-PROOF.json`,JSON.stringify({class:'local mock-browser',results},null,2));
}

async function roleAcknowledgementProof(browser,html,width,height,out){
 for(const kind of ['reset-conflict','reset-uncertain','icon-mismatch','variants-mismatch','icon-uncertain','variants-uncertain','reset-confirmed','receipt-event','receipt-command','receipt-version','receipt-status']){
  const page=await browser.newPage({viewport:{width,height},colorScheme:'dark',reducedMotion:'reduce'}),errors=[];
  page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});
  await page.setContent(html);await page.waitForFunction(()=>document.querySelector('.usage-total')?.textContent==='40');await navigationClick(page,'.library-nav a[href="#roles"]');await page.locator('[data-role-open="designer"]').waitFor();
  await page.evaluate(kind=>{const role=window.roles.find(r=>r.id==='designer');role.source='user_override';role.canonical_version='builtin:'+'d'.repeat(64);role.active_version='user_override:'+'f'.repeat(64);role.source_event_ids=[];role.avatar_variants=[];window.roleReceiptPatch=kind==='receipt-event'?{event_id:'unrelated-command'}:kind==='receipt-command'?{command:'ROLE_MANIFEST_CREATE'}:kind==='receipt-version'?{active_version:'unrelated-version'}:kind==='receipt-status'?{status:'rejected'}:null;window.roleConflict=kind==='reset-conflict';window.roleUncertain=kind.endsWith('uncertain')||kind==='reset-confirmed';if(kind.startsWith('icon'))window.roleReadbackPatch={lucide_icon:'palette'};if(kind.startsWith('variants'))window.roleReadbackPatch={avatar_variants:[{id:'command',asset_digest:'c'.repeat(64),structural_roles:['CTRL']}]};},kind);
  await page.locator('[data-library-load]').click();await page.locator('[data-role-open="designer"]').click();const form=page.locator('[data-role-form]');await form.waitFor();const actions=width<=700?page.locator('#inspector footer'):form.locator('.editor-actions');
  await form.locator('[name=purpose]').fill('Keep this exact draft');
  if(kind.startsWith('icon')){await form.locator('[data-role-more] summary').click();await form.locator('[name=lucide_icon]').fill('pencil');}
  await actions.getByRole('button',{name:kind.startsWith('reset')?'Reset to built-in':'Save role',exact:true}).click();
  await form.getByText(kind==='reset-conflict'?/changed elsewhere/:/Save not confirmed/).waitFor();
  const request=await page.evaluate(()=>structuredClone(window.lastRoleWrite));
  if(kind==='reset-conflict'||kind==='reset-uncertain')await page.evaluate(()=>{const r=window.roles.find(r=>r.id==='designer');r.active_version='user_override:'+'9'.repeat(64);r.source='user_override';r.purpose='Unrelated concurrent override';});
  await actions.getByRole('button',{name:kind==='reset-confirmed'?'Reset to built-in':'Reload current roles'}).click();
  if(kind==='reset-confirmed'){if(width<=700)await page.locator('#inspector').waitFor({state:'hidden'});else await form.waitFor({state:'detached'});assert.equal(await page.locator('[data-library-status]').textContent(),'Saved');assert.deepEqual(await page.evaluate(()=>window.lastRoleWrite),request,'ambiguous reset retry retains exact command identity');}
  else{
   await form.getByText(/Review your preserved draft/).waitFor({timeout:4000});assert.equal(await form.locator('[name=purpose]').inputValue(),'Keep this exact draft');assert.notEqual(await page.locator('[data-library-status]').textContent(),'Saved');
   if(kind.startsWith('icon'))assert.equal(await form.locator('[name=lucide_icon]').inputValue(),'pencil');
   if(kind.startsWith('variants'))assert.deepEqual(request.manifest.avatar_variants,[]);
   await form.locator('[data-editor-status]').scrollIntoViewIfNeeded();await page.screenshot({path:`${out}/role-${kind}-${width}.png`});await actions.getByRole('button',{name:'Cancel',exact:true}).click();assert.ok(await page.locator('[data-role-open="designer"]').evaluate(e=>e===document.activeElement));
  }
  assert.deepEqual(errors,[]);await page.close();
 }
}

async function wordmarkRecoveryProof(browser,html,out){
 for(const [width,height] of [[1440,1000],[390,844]])for(const initiallyFailed of [false,true]){
  const page=await browser.newPage({viewport:{width,height},colorScheme:'dark',reducedMotion:'reduce'}),errors=[],network=[];
  page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(r.url().startsWith('http'))network.push(r.url());});
  const canonical=html.match(/class="wordmark" src="([^"]+)"/)[1],broken='data:image/png;base64,AA==';
  await page.setContent(initiallyFailed?html.replace(canonical,broken):html);await page.waitForFunction(()=>document.querySelector('.usage-total')?.textContent==='40');
  const img=page.locator('.wordmark'),home=page.locator('.wordmark-wrap'),fallback=home.locator('.brand-label');
  assert.equal(await home.getAttribute('aria-label'),'Overview');const bounds=await home.boundingBox();assert.ok(bounds.height>=44);
  if(!initiallyFailed){await img.evaluate(i=>i.decode());assert.equal(await img.evaluate(i=>i.naturalWidth),1475);assert.equal(await fallback.evaluate(e=>getComputedStyle(e).display),'none');await img.evaluate((i,url)=>i.src=url,broken);}
  await page.waitForFunction(()=>document.querySelector('.wordmark').hidden);assert.ok(await fallback.isVisible());assert.equal(await fallback.textContent(),'SWARM');assert.deepEqual(await home.boundingBox(),bounds,'failed image never changes home link bounds');assert.equal(await page.evaluate(()=>document.documentElement.dataset.swarmHost),'initialized','external image failure is not host disconnection');
  await home.focus();assert.ok(await home.evaluate(e=>e===document.activeElement));await page.keyboard.press('Enter');await page.waitForFunction(()=>location.hash==='#projects'&&document.activeElement===document.querySelector('#main h1'));assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
  if(!initiallyFailed)await page.screenshot({path:`${out}/wordmark-failure-${width}.png`});
  await img.evaluate((i,url)=>{i.src=url;return i.decode();},canonical);await page.waitForFunction(()=>!document.querySelector('.wordmark').hidden);assert.equal(await img.evaluate(i=>i.naturalWidth),1475);assert.equal(await fallback.evaluate(e=>getComputedStyle(e).display),'none');assert.deepEqual(await home.boundingBox(),bounds,'recovery preserves home link bounds');
  if(!initiallyFailed)await page.screenshot({path:`${out}/wordmark-recovered-${width}.png`});assert.deepEqual(errors,[]);assert.deepEqual(network,[]);await page.close();
 }
}
